SourceCode.Declaration:
abstract class XAPI_APIPostProcessorBase
{
    protected XAPI_APIS api;
}

Method.Source:
public XAPI_APIS parmApi(XAPI_APIS _api = api)
{
    api = _api;
    return api;
}

/// <summary>
/// Returns the post-processor for the given API, or null if none is registered.
/// </summary>
public static XAPI_APIPostProcessorBase construct(XAPI_APIS _api)
{
    XAPI_APIPostProcessorBase postProc;

    switch (_api)
    {
        case XAPI_APIS::CreateContractPart:
            postProc = new XAPI_APIPostProcessor_ContractPart();
            break;

        default:
            return null;
    }

    postProc.parmApi(_api);
    return postProc;
}
